-- Kalo · pollo sudado y pollo frito (con piel, sin hueso); «pollo asado» ya no aparece al buscar «pollo apanado»
insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('pollo-sudado', 'Pollo sudado', array['pollo guisado', 'pollo en salsa', 'sudado de pollo', 'pollo cocido'], 'proteinas', 'Presa con piel guisada. USDA sr_legacy · 171051', '{"vit_d_ug": 0.0, "vit_a_ug": 44.0, "selenio_ug": 18.0, "fibra_g": 0.0, "hierro_mg": 1.16, "magnesio_mg": 19.0, "fosforo_mg": 139.0, "sodio_mg": 67.0, "cobre_mg": 0.06, "manganeso_mg": 0.02, "colesterol_mg": 78.0, "grasa_sat_g": 3.5, "vit_c_mg": 0.0, "b1_mg": 0.05, "b2_mg": 0.15, "folato_ug": 5.0, "b12_ug": 0.2, "proteina_g": 24.68, "calcio_mg": 13.0, "potasio_mg": 166.0, "zinc_mg": 1.76, "grasa_g": 12.56, "carbos_g": 0.0, "kcal": 219.0, "b3_mg": 5.59, "b6_mg": 0.22, "vit_k_ug": 2.1, "azucar_g": 0.0, "vit_e_mg": 0.27}'::jsonb, '{"texto": "1 presa (pernil o contramuslo)", "gramos": 100}'::jsonb, '[{"texto": "1 presa (pernil o contramuslo)", "gramos": 100}, {"texto": "1 presa de pechuga", "gramos": 150}, {"texto": "1 ala", "gramos": 45}, {"texto": "100 g", "gramos": 100}]'::jsonb, null, 'pollo sudado pollo guisado pollo en salsa sudado de pollo pollo cocido') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('pollo-frito', 'Pollo frito', array['pollo broaster', 'pollo frito casero', 'presa frita'], 'proteinas', 'Presa con piel enharinada y frita; ya incluye el aceite. USDA sr_legacy · 171449', '{"vit_a_ug": 27.0, "vit_d_ug": 0.1, "colesterol_mg": 90.0, "grasa_sat_g": 4.06, "vit_c_mg": 0.0, "b1_mg": 0.09, "b2_mg": 0.19, "proteina_g": 28.56, "fibra_g": 0.1, "hierro_mg": 1.38, "magnesio_mg": 25.0, "fosforo_mg": 191.0, "sodio_mg": 84.0, "cobre_mg": 0.07, "manganeso_mg": 0.03, "grasa_g": 14.92, "carbos_g": 3.15, "kcal": 269.0, "b3_mg": 8.99, "b6_mg": 0.41, "calcio_mg": 17.0, "potasio_mg": 234.0, "zinc_mg": 2.04, "azucar_g": 0.0, "vit_e_mg": 0.63, "vit_k_ug": 2.4, "folato_ug": 9.0, "b12_ug": 0.31, "selenio_ug": 21.7}'::jsonb, '{"texto": "1 presa (pernil o contramuslo)", "gramos": 100}'::jsonb, '[{"texto": "1 presa (pernil o contramuslo)", "gramos": 100}, {"texto": "1 presa de pechuga", "gramos": 150}, {"texto": "1 ala", "gramos": 45}, {"texto": "100 g", "gramos": 100}]'::jsonb, null, 'pollo frito pollo broaster pollo frito casero presa frita') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
update public.alimentos set sinonimos = array_remove(sinonimos, 'pollo apanado'), busqueda = trim(replace(busqueda, 'pollo apanado', '')) where id = 'pollo-asado';
